  using(var db=new LibraryStore(System.IO.Path.Combine(directory,"db"))){db.AddRoot(directory);db.AddRoot(directory);Assert(db.Roots().Count==1,"Folder deduplication");}
  var order=new PlaybackOrder(123);order.Reset(4,0);Assert(order.Next(4,3,true)==-1,"Repeat off stops at end");order.Repeat=RepeatMode.All;Assert(order.Next(4,3,true)==0,"Repeat all wraps queue");order.Repeat=RepeatMode.One;Assert(order.Next(4,2,true)==2,"Repeat one restarts on natural end");Assert(order.Next(4,2,false)==3,"Manual next bypasses repeat one");order.Repeat=RepeatMode.Off;order.SetShuffle(true,8,0);int current=0;var visited=new HashSet<int>{0};for(int i=0;i<7;i++){current=order.Next(8,current,true);Assert(current>=0&&visited.Add(current),"Shuffle unique item "+i);}Assert(order.Next(8,current,true)==-1,"Shuffle stops after full cycle");Assert(order.Previous(current)>=0,"Shuffle previous uses history");order.Repeat=RepeatMode.All;Assert(order.Next(8,current,true)>=0,"Shuffle repeat all starts new cycle");Assert(order.Next(0,-1,true)==-1,"Empty queue stops safely");
  var active=new Track{Path="C:\\music\\active.flac"};var duplicate=new Track{Path="c:\\MUSIC\\active.flac"};var other=new Track{Path="C:\\music\\other.flac"};Track[] visualRows=[active,duplicate,other];PlaybackVisuals.Update(visualRows,active,true);Assert(active.IsCurrent&&duplicate.IsCurrent&&active.IsAnimating&&duplicate.IsAnimating&&!other.IsCurrent,"Current track marked across views by file path");PlaybackVisuals.Update(visualRows,active,false);Assert(active.IsCurrent&&!active.IsAnimating,"Pause keeps highlight and freezes animation");PlaybackVisuals.Update(visualRows,other,true);Assert(!active.IsCurrent&&!active.IsAnimating&&other.IsAnimating,"Track change transfers playing indicator");PlaybackVisuals.Update(visualRows,null,false);Assert(visualRows.All(t=>!t.IsCurrent&&!t.IsAnimating),"Stop clears all playing indicators");Assert(!JsonSerializer.Serialize(active).Contains("IsCurrent"),"Playback state is not persisted in library");
  double offset=0;bool bounded=true;for(int i=0;i<60;i++){double next=SmoothScroll.Step(offset,500,1.0/60);bounded&=next>=offset&&next<=500;offset=next;}Assert(bounded,"Smooth scroll stays bounded throughout animation");Assert(Math.Abs(offset-500)<.01,"Smooth scroll converges without overshooting");Assert(SmoothScroll.Step(100,100,.016)==100,"Smooth scroll is stable at rest");
  string preferencesPath=System.IO.Path.Combine(directory,"panel-test.json");var preferences=new PanelPreferences{Width=510,ShowCover=false,ShowArtist=false};preferences.HiddenFields.Add("Dosya");preferences.HiddenFields.Add("Vorbis / vendor");preferences.Save(preferencesPath);var restored=PanelPreferences.Load(preferencesPath);Assert(restored.Width==510&&!restored.ShowCover&&!restored.ShowArtist,"Panel width and section preferences persist");Assert(!restored.IsVisible("DOSYA")&&!restored.IsVisible("vorbis / VENDOR"),"Panel field preferences ignore key casing");Assert(restored.IsVisible("Yeni etiket"),"New metadata fields remain configurable and visible");restored.HiddenFields.Remove("Dosya");restored.Save(preferencesPath);Assert(PanelPreferences.Load(preferencesPath).IsVisible("Dosya"),"Hidden panel fields can be restored");await File.WriteAllTextAsync(preferencesPath,"{broken");Assert(PanelPreferences.Load(preferencesPath).ShowCover,"Invalid panel preferences recover defaults");await File.WriteAllTextAsync(preferencesPath,"{\"Width\":9999,\"HiddenFields\":null}");var boundedPreferences=PanelPreferences.Load(preferencesPath);Assert(boundedPreferences.Width==640&&boundedPreferences.IsVisible("Dosya"),"Panel width and null field list are validated");
  var devices=AudioEngine.Devices();results.Add(new{name="Audio devices enumerated",passed=true,count=devices.Count});
  if(devices.Count>0){string silence=System.IO.Path.Combine(directory,"silence.wav");var f=new WaveFormat(48000,16,2);using(var writer=new WaveFileWriter(silence,f))writer.Write(new byte[f.AverageBytesPerSecond],0,f.AverageBytesPerSecond);using var engine=new AudioEngine();engine.Play(silence,null,false);Assert(engine.IsPlaying,"WASAPI shared silent playback starts");engine.Toggle();Assert(engine.IsPaused,"WASAPI pause");engine.Position=TimeSpan.FromMilliseconds(100);Assert(Math.Abs(engine.Position.TotalMilliseconds-100)<2,"WASAPI seek");engine.Toggle();Assert(engine.IsPlaying,"WASAPI resume");engine.Stop();Assert(!engine.IsPlaying&&!engine.IsPaused,"WASAPI stop and release");}
  string anti=System.IO.Path.Combine(directory,"opposite-channels.wav");using(var writer=new WaveFileWriter(anti,new WaveFormat(44100,16,2))){for(int i=0;i<4410;i++){short sample=(short)(Math.Sin(i*2*Math.PI*440/44100)*20000);writer.Write(BitConverter.GetBytes(sample),0,2);writer.Write(BitConverter.GetBytes((short)-sample),0,2);}}
  var antiTrack=await MetadataReader.Read(anti,default,directory);var antiWave=await WaveformAnalyzer.Get(antiTrack,System.IO.Path.Combine(directory,"waveforms"),default);Assert(antiWave.Valid&&antiWave.Mid.Max()>0.1,"Opposite-phase stereo is not erased by mono cancellation");
  string silent=System.IO.Path.Combine(directory,"wave-silence.wav");using(var writer=new WaveFileWriter(silent,new WaveFormat(44100,16,2)))writer.Write(new byte[17640],0,17640);
  var silentTrack=await MetadataReader.Read(silent,default,directory);var silentWave=await WaveformAnalyzer.Get(silentTrack,System.IO.Path.Combine(directory,"waveforms"),default);Assert(silentWave.Low.Concat(silentWave.Mid).Concat(silentWave.High).All(v=>v==0),"Silent file has zero waveform energy");
  using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();bool stopped=false;try{await WaveformAnalyzer.Get(antiTrack,System.IO.Path.Combine(directory,"cancelled-wave"),cancelled.Token);}catch(OperationCanceledException){stopped=true;}Assert(stopped,"Waveform analysis can be cancelled");}
  int[] values=[-8388608,-8388607,-1,0,1,8388606,8388607,0];string exact=System.IO.Path.Combine(directory,"24bit-values.wav");using(var writer=new WaveFileWriter(exact,new WaveFormat(44100,24,2)))foreach(int value in values){byte[] bytes=[(byte)value,(byte)(value>>8),(byte)(value>>16)];writer.Write(bytes,0,3);}using(var input=new WaveFileReader(exact)){var shared=AudioEngine.SharedSource(input);var bytes=new byte[values.Length*4];int count=shared.Read(bytes,0,bytes.Length);Assert(count==bytes.Length&&values.Select((v,i)=>BitConverter.ToSingle(bytes,i*4)==v/8388608f).All(v=>v),"Shared float transfer preserves 24-bit sample values exactly");}
  if(devices.Count>0){string diagnostics=System.IO.Path.Combine(directory,"audio-matrix");await AudioDiagnostics.Run(diagnostics);using var report=JsonDocument.Parse(await File.ReadAllTextAsync(System.IO.Path.Combine(diagnostics,"audio-results.json")));foreach(var check in report.RootElement.GetProperty("results").EnumerateArray())Assert(check.GetProperty("passed").GetBoolean(),$"WASAPI shared {check.GetProperty("bits")} bit / {check.GetProperty("rate")} Hz actually advances without errors");}
  string inbox=System.IO.Path.Combine(directory,"auto-import"),state=System.IO.Path.Combine(directory,"ui-state");Directory.CreateDirectory(inbox);string demo=System.IO.Path.Combine(inbox,"01 Dalga formu.flac");await ProcessTool.Run(Paths.Tool("ffmpeg"),["-v","error","-y","-f","lavfi","-i","anullsrc=r=44100:cl=stereo","-t","30","-c:a","flac",demo]);var demoTrack=await MetadataReader.Read(demo,default,state);using(var ui=new LibraryStore(state)){ui.AddRoot(inbox);var visual=new System.Windows.Media.DrawingVisual();using(var d=visual.RenderOpen()){d.DrawRectangle(new System.Windows.Media.LinearGradientBrush(System.Windows.Media.Colors.IndianRed,System.Windows.Media.Colors.DarkSlateBlue,45),null,new System.Windows.Rect(0,0,400,400));d.DrawEllipse(System.Windows.Media.Brushes.Gold,null,new System.Windows.Point(120,140),80,80);d.DrawEllipse(System.Windows.Media.Brushes.DarkCyan,null,new System.Windows.Point(320,340),180,170);}var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(400,400,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));string cover=System.IO.Path.Combine(state,"fixture-cover.png");using(var output=File.Create(cover))encoder.Save(output);demoTrack.Cover=cover;demoTrack.Album="Görsel kontrol";demoTrack.AlbumArtist=demoTrack.Artist="Ahenk";for(int i=1;i<=20;i++){string path=System.IO.Path.Combine(inbox,$"{i:00} Sessiz deneme.flac");File.Copy(demo,path,true);var row=JsonSerializer.Deserialize<Track>(JsonSerializer.Serialize(demoTrack))!;row.Path=path;row.Title=$"Sessiz deneme {i:00}";row.Number=(uint)i;ui.Save(row);}}
  await PerformanceRegressionTests.Run(directory,Assert);OscilloscopeTests.Run(Assert);VisualizationTests.Run(directory,Assert);
  await File.WriteAllTextAsync(System.IO.Path.Combine(directory,"test-results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));
