 static bool EqualPcm(string a,string b)
 {
  byte[] Hash(string p){using var r=new WaveFileReader(p);using var sha=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);var buffer=new byte[r.WaveFormat.BlockAlign*4096];int read;while((read=r.Read(buffer,0,buffer.Length))>0)sha.AppendData(buffer,0,read);return sha.GetHashAndReset();}return Hash(a).SequenceEqual(Hash(b));
 }
 static byte[] HashProvider(IWaveProvider source){using var hash=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);var buffer=new byte[source.WaveFormat.BlockAlign*4096];int count;while((count=source.Read(buffer,0,buffer.Length))>0)hash.AppendData(buffer,0,count);return hash.GetHashAndReset();}
 static void AddRepeatedComments(string path)
 {
  byte[] original=File.ReadAllBytes(path);using var output=new MemoryStream();output.Write(original,0,4);int offset=4;
  while(true){byte kind=original[offset];int len=(original[offset+1]<<16)|(original[offset+2]<<8)|original[offset+3];if((kind&127)==4){using var payload=new MemoryStream();using var r=new BinaryReader(new MemoryStream(original,offset+4,len),Encoding.UTF8);using var w=new BinaryWriter(payload,Encoding.UTF8,true);uint vendor=r.ReadUInt32();w.Write(vendor);w.Write(r.ReadBytes((int)vendor));uint count=r.ReadUInt32();w.Write(count+2);for(int i=0;i<count;i++){uint n=r.ReadUInt32();w.Write(n);w.Write(r.ReadBytes((int)n));}foreach(var tag in new[]{"CUSTOM_REPEAT=Birinci değer","CUSTOM_REPEAT=İkinci değer"}){var bytes=Encoding.UTF8.GetBytes(tag);w.Write(bytes.Length);w.Write(bytes);}byte[] block=payload.ToArray();output.WriteByte(kind);output.WriteByte((byte)(block.Length>>16));output.WriteByte((byte)(block.Length>>8));output.WriteByte((byte)block.Length);output.Write(block);}else output.Write(original,offset,len+4);offset+=len+4;if((kind&128)!=0)break;}
  output.Write(original,offset,original.Length-offset);File.WriteAllBytes(path,output.ToArray());
 }
